{
  "summary": "This candidate possesses strong, quantifiable experience in building robust data pipelines and optimizing ETL processes. However, the resume presents a significant disconnect, as the summary claims a focus on frontend engineering while all work experience is rooted in Data Engineering.",
  "wouldAdvance": "maybe",
  "strengths": [
    {
      "point": "Demonstrates significant impact on compute cost and efficiency.",
      "evidence": "Rewrote a slow Spark job so a 6-hour aggregation finishes in 50 minutes, saving about $3,000 a month in compute."
    },
    {
      "point": "Manages high-volume data ingestion and improves reliability.",
      "evidence": "Built Airflow pipelines that load 40 million events a day into Snowflake, cutting nightly job failures from 12 a week to 1."
    },
    {
      "point": "Has experience designing and implementing complex data modeling layers.",
      "evidence": "Designed a dbt model layer of 85 tables with tests, replacing 30 hand-written SQL reports."
    },
    {
      "point": "Successfully implemented critical data quality and deduplication systems.",
      "evidence": "Built a Kafka consumer that deduplicates 2 million records a day with under 0.01% loss."
    }
  ],
  "issues": [
    {
      "severity": "high",
      "problem": "The stated career target in the summary contradicts the entire work history.",
      "evidence": "Frontend engineer with 6 years of experience building fast, accessible React interfaces.",
      "suggestion": "Update the summary to accurately reflect the Data Engineering focus of the experience."
    },
    {
      "severity": "medium",
      "problem": "A listed skill is not supported by the work experience.",
      "evidence": "React",
      "suggestion": "Either provide a bullet point detailing React usage in a project or remove it from the skills list."
    },
    {
      "severity": "low",
      "problem": "The summary is a self-claim rather than a proof of capability.",
      "evidence": "Frontend engineer with 6 years of experience building fast, accessible React interfaces.",
      "suggestion": "Replace the summary with a brief, achievement-focused professional profile that highlights core competencies."
    }
  ]
}
